`timescale 1ns / 1ps
// Testbench: hello_world executes on the trit-native VTX1 core
//
// Loads build/hello_world.memh (real assembler output; regenerated by
// `task test-core`) into a word memory, runs vtx1_core until WFI, and
// checks the program's effects:
//   - "Hello, VTX1!" written to word addresses 0x2000..0x200B
//   - character count 12 at 0x2100
//   - completion flag 1 at 0x2104
//   - retired instruction count matches the ISA simulator (vtxsim): 93
//
// This is the code-to-silicon milestone test: the same binary runs in the
// ISA simulator and on the RTL, and both must agree.

module tb_vtx1_core;

    reg clk = 0;
    reg rst_n = 0;
    always #5 clk = ~clk;

    // Unified word-addressed memory (synchronous, 1-cycle)
    reg [35:0] mem [0:16383];

    wire        mem_req, mem_wr;
    wire [31:0] mem_addr;
    wire [35:0] mem_wdata;
    reg  [35:0] mem_rdata;

    always @(posedge clk) begin
        if (mem_req && !mem_wr)
            mem_rdata <= mem[mem_addr[13:0]];
        if (mem_req && mem_wr)
            mem[mem_addr[13:0]] <= mem_wdata;
    end

    wire        halted, trap;
    wire [31:0] trap_pc, retired, cycles;

    vtx1_core core (
        .clk(clk), .rst_n(rst_n),
        .mem_req(mem_req), .mem_wr(mem_wr),
        .mem_addr(mem_addr), .mem_wdata(mem_wdata), .mem_rdata(mem_rdata),
        .halted(halted), .trap(trap), .trap_pc(trap_pc),
        .retired(retired), .cycles(cycles)
    );

    // Decode a canonical trit word to its balanced value
    function signed [35:0] wordval(input [35:0] w);
        integer i;
        reg signed [2:0] t;
        begin
            wordval = 36'sd0;
            for (i = 0; i < 18; i = i + 1) begin
                case (w[35-2*i -: 2])
                    2'b00:   t = -3'sd1;
                    2'b01:   t = 3'sd0;
                    2'b10:   t = 3'sd1;
                    default: t = 3'sd0;
                endcase
                wordval = wordval * 3 + t;
            end
        end
    endfunction

    integer errors;
    integer i;
    integer timeout;
    reg [8*16-1:0] expected = "Hello, VTX1!";
    reg [8*16-1:0] got;
    reg signed [35:0] v;

    task check(input [255:0] name, input signed [35:0] gotv, input signed [35:0] wantv);
        if (gotv !== wantv) begin
            $display("  FAIL: %0s = %0d, want %0d", name, gotv, wantv);
            errors = errors + 1;
        end
    endtask

    initial begin
        errors = 0;
        $readmemh("build/hello_world.memh", mem);

        rst_n = 0;
        repeat (4) @(posedge clk);
        rst_n = 1;

        timeout = 0;
        while (!halted && timeout < 10000) begin
            @(posedge clk);
            timeout = timeout + 1;
        end

        $display("=== hello_world on the VTX1 RTL core ===");
        if (!halted) begin
            $display("  FAIL: core did not halt within %0d cycles", timeout);
            errors = errors + 1;
        end
        if (trap) begin
            $display("  FAIL: core trapped at PC 0x%0h", trap_pc);
            errors = errors + 1;
        end

        // The output string
        got = "";
        for (i = 0; i < 12; i = i + 1) begin
            v = wordval(mem['h2000 + i]);
            got = {got[8*15-1:0], v[7:0]};
        end
        $display("RTL says: \"%0s\"", got);
        for (i = 0; i < 12; i = i + 1) begin
            v = wordval(mem['h2000 + i]);
            if (v !== expected[8*(12-i)-1 -: 8]) begin
                $display("  FAIL: output[%0d] = %0d ('%c'), want '%c'",
                         i, v, v[7:0], expected[8*(12-i)-1 -: 8]);
                errors = errors + 1;
            end
        end
        check("NUL terminator",  wordval(mem['h200C]), 0);
        check("character count", wordval(mem['h2100]), 12);
        check("completion flag", wordval(mem['h2104]), 1);

        // Cross-check against the ISA simulator: vtxsim retires 93
        // instruction words for this program.
        check("retired words (vs vtxsim)", retired, 93);
        $display("Cycles: %0d  Retired: %0d  CPI: %0d.%02d",
                 cycles, retired, cycles / retired, (cycles * 100 / retired) % 100);

        if (errors == 0)
            $display("=== PASS: the toolchain-simulator-RTL loop is closed ===");
        else
            $display("=== FAIL: %0d error(s) ===", errors);
        $finish;
    end

endmodule
